// Generated by Codex and not thoroughly checked for correctness.
func TestAllowanceRefillAndIdentityIsolation(t *testing.T) {
	for _, testCase := range []struct {
		name   string
		policy ratelimit.Policy
		burst  int
		refill time.Duration
	}{
		{"general traffic", ratelimit.General, 10, time.Second},
		{"write traffic", ratelimit.Write, 10, 2 * time.Second},
		{"login traffic", ratelimit.Login, 10, 6 * time.Second},
		{"callback traffic", ratelimit.Callback, 10, 6 * time.Second},
		{"Codeforces cooldown", ratelimit.Codeforces, 1, time.Minute},
	} {
		t.Run(testCase.name, func(t *testing.T) {
			now := time.Now()
			service := newService(t, ratelimit.DefaultConfig(), func() time.Time { return now })
			for range testCase.burst {
				assertAllowance(t, service, testCase.policy, "first", true, 0)
			}
			assertAllowance(t, service, testCase.policy, "first", false, testCase.refill)
			assertAllowance(t, service, testCase.policy, "second", true, 0)
			now = now.Add(testCase.refill / 2)
			assertAllowance(t, service, testCase.policy, "first", false, testCase.refill/2)
			now = now.Add(testCase.refill / 2)
			assertAllowance(t, service, testCase.policy, "first", true, 0)
		})
	}
}

// Generated by Codex and not thoroughly checked for correctness.
func TestConcurrentCodeforcesAttemptsAllowOnlyOne(t *testing.T) {
	now := time.Now()
	service := newService(t, ratelimit.DefaultConfig(), func() time.Time { return now })
	var allowed atomic.Int32
	var workers sync.WaitGroup
	for range 100 {
		workers.Go(func() {
			if ok, _ := service.Allow(ratelimit.Codeforces, "same-user"); ok {
				allowed.Add(1)
			}
		})
	}
	workers.Wait()
	if allowed.Load() != 1 {
		t.Fatalf("allowed attempts = %d, want 1", allowed.Load())
	}
}

// Generated by Codex and not thoroughly checked for correctness.
func TestCapacityAndIdleCleanupPreserveActiveLimits(t *testing.T) {
	now := time.Now()
	config := ratelimit.DefaultConfig()
	config.MaxEntries = 2
	service := newService(t, config, func() time.Time { return now })
	assertAllowance(t, service, ratelimit.Codeforces, "first", true, 0)
	assertAllowance(t, service, ratelimit.Codeforces, "second", true, 0)
	assertAllowance(t, service, ratelimit.Codeforces, "third", false, time.Minute)
	assertAllowance(t, service, ratelimit.Codeforces, "first", false, time.Minute)
	now = now.Add(9 * time.Minute)
	assertAllowance(t, service, ratelimit.Codeforces, "first", true, 0)
	now = now.Add(time.Minute)
	assertAllowance(t, service, ratelimit.Codeforces, "third", true, 0)
	assertAllowance(t, service, ratelimit.Codeforces, "fourth", false, time.Minute)
}

