// Generated by Codex and not thoroughly checked for correctness.
func TestInvalidConfigurationAndPolicy(t *testing.T) {
	for _, testCase := range []struct {
		name   string
		change func(*ratelimit.Config)
	}{
		{"zero general rate is rejected", func(config *ratelimit.Config) { config.GeneralPerMinute = 0 }},
		{"zero write rate is rejected", func(config *ratelimit.Config) { config.WritePerMinute = 0 }},
		{"zero authentication rate is rejected", func(config *ratelimit.Config) { config.AuthPerMinute = 0 }},
		{"zero cooldown is rejected", func(config *ratelimit.Config) { config.CodeforcesCooldown = 0 }},
		{"zero storage capacity is rejected", func(config *ratelimit.Config) { config.MaxEntries = 0 }},
	} {
		t.Run(testCase.name, func(t *testing.T) {
			config := ratelimit.DefaultConfig()
			testCase.change(&config)
			if _, err := ratelimit.New(config); err == nil {
				t.Fatal("invalid configuration was accepted")
			}
		})
	}
	service, err := ratelimit.New(ratelimit.DefaultConfig())
	if err != nil {
		t.Fatal(err)
	}
	assertAllowance(t, service, ratelimit.Policy(255), "user", false, time.Minute)
}

// Generated by Codex and not thoroughly checked for correctness.
func TestRejectionIncludesRoundedRetryAndTypedError(t *testing.T) {
	gin.SetMode(gin.TestMode)
	for _, delay := range []time.Duration{0, time.Millisecond, 1500 * time.Millisecond} {
		response := httptest.NewRecorder()
		ctx, _ := gin.CreateTestContext(response)
		ratelimit.Reject(ctx, delay)
		wantRetry := "1"
		if delay > time.Second {
			wantRetry = "2"
		}
		if response.Code != http.StatusTooManyRequests || response.Header().Get("Retry-After") != wantRetry || !ctx.IsAborted() || response.Header().Get("Cache-Control") != "no-store" {
			t.Fatalf("unexpected rejection: code=%d headers=%v aborted=%v", response.Code, response.Header(), ctx.IsAborted())
		}
		var payload testutil.APIResponse
		if err := json.Unmarshal(response.Body.Bytes(), &payload); err != nil {
			t.Fatal(err)
		}
		if payload.Error == "" {
			t.Fatal("missing error message")
		}
	}
}

func newService(t *testing.T, config ratelimit.Config, now func() time.Time) *ratelimit.Service {
	t.Helper()
	service, err := ratelimit.New(config, ratelimit.WithClock(now))
	if err != nil {
		t.Fatal(err)
	}
	return service
}

func assertAllowance(t *testing.T, service *ratelimit.Service, policy ratelimit.Policy, identity string, wantAllowed bool, wantRetry time.Duration) {
	t.Helper()
	allowed, retry := service.Allow(policy, identity)
	if allowed != wantAllowed || retry != wantRetry {
		t.Fatalf("policy %s allowance = %v, %s; want %v, %s", strconv.Itoa(int(policy)), allowed, retry, wantAllowed, wantRetry)
	}
}
